<?php
require '../config/db.php'; require '../config/auth.php'; require_role('admin','login.php'); $u=current_user();
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['action']??''; $id=(int)($_POST['id']??0);
  if($action==='save'){ $title=trim($_POST['title']??''); $content=trim($_POST['content']??''); if($title===''||$content===''){flash('error','Title and content are required.');} elseif($id){$pdo->prepare('UPDATE announcements SET title=?,content=? WHERE id=?')->execute([$title,$content,$id]);log_activity($pdo,$u['id'],'Updated announcement',$title);flash('success','Announcement updated.');} else {$pdo->prepare('INSERT INTO announcements(title,content,published_by) VALUES(?,?,?)')->execute([$title,$content,$u['id']]);log_activity($pdo,$u['id'],'Published announcement',$title);flash('success','Announcement published.');}}
  if($action==='delete'&&$id){$s=$pdo->prepare('SELECT title FROM announcements WHERE id=?');$s->execute([$id]);$title=$s->fetchColumn();$pdo->prepare('DELETE FROM announcements WHERE id=?')->execute([$id]);log_activity($pdo,$u['id'],'Deleted announcement',(string)$title);flash('success','Announcement deleted.');}
  redirect('announcements.php'); }
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM announcements WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT a.*,u.full_name author FROM announcements a LEFT JOIN users u ON u.id=a.published_by ORDER BY a.published_at DESC')->fetchAll();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcements</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><header class="topbar"><div><button class="btn light mobile-toggle" data-nav-toggle>☰</button><div class="eyebrow">Communication</div><h1>Announcements.</h1></div></header><?php if($m=flash('success')):?><div class="notice"><?=e($m)?></div><?php endif;if($m=flash('error')):?><div class="notice error"><?=e($m)?></div><?php endif;?><section class="grid two"><div class="card"><h2><?=$edit?'Edit':'Publish'?> announcement</h2><form method="post" class="grid"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label class="field">Title<input name="title" maxlength="180" required value="<?=e($edit['title']??'')?>"></label><label class="field">Content<textarea name="content" rows="8" required><?=e($edit['content']??'')?></textarea></label><div class="actions"><button class="btn">Save announcement</button><?php if($edit):?><a class="btn light" href="announcements.php">Cancel</a><?php endif?></div></form></div><div class="card" data-live-scope><h2>Published announcements</h2><div class="live-filter-bar"><label class="field live-search-field">Search<input class="search" type="search" data-live-search placeholder="Start typing to filter announcements..."></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><div data-live-list><div class="live-empty" data-live-empty hidden>No announcements match your search.</div><?php if(!$rows):?><p class="muted">No announcements yet.</p><?php endif;foreach($rows as $r):?><article data-live-item data-search="<?=e(strtolower($r['title'].' '.$r['content'].' '.($r['author']??'Administrator').' '.$r['published_at']))?>" style="padding:14px 0;border-bottom:1px solid var(--line)"><h3><?=e($r['title'])?></h3><p class="muted"><?=date('M j, Y g:i A',strtotime($r['published_at']))?> · <?=e($r['author']??'Administrator')?></p><p><?=nl2br(e(mb_strimwidth($r['content'],0,220,'…')))?></p><div class="actions"><a class="btn light small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this announcement?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Delete</button></form></div></article><?php endforeach?></div></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
